typedef struct
{
    const CHAR *name;
    UINT        tls_1_3;        /* 0: TLS 1.2, 1: TLS 1.3 */
    UINT        ecc;            /* the ECC table (ECDHE ServerKeyExchange in TLS 1.2) */
    UINT        client_verify;  /* server requests a client certificate */
    UINT        hrr;            /* the client's first key share is a group the server lacks */
    UINT        small_pool;     /* server's packets small enough that Certificate chains */
    UINT        action;
    UINT        fault;
    UINT        side;
    UINT        occurrence;     /* the n-th matching call on that side fails */
    UCHAR       handshake_type; /* for F_RECORD_SEND */
    UINT        expect;         /* status of the failing side's call (both sides for F_NONE) */
} LEG;

